exercises.reference:
import math

def attacker_success(q, z):
    p = 1.0 - q
    if q >= p:
        return 1.0
    lam = z * q / p
    total, poisson = 1.0, math.exp(-lam)
    for k in range(z + 1):
        if k > 0:
            poisson *= lam / k
        total -= poisson * (1 - (q / p) ** (z - k))
    return total

